package config

// Manifest entry of a compiled in platform, its value a secret when asked
func platformVar(name string, required, secret bool, category, description, prompt string) PlatformEnvVar {
	return PlatformEnvVar{Name: name, Required: required, Secret: secret,
		Var: EnvVar{Description: description, Prompt: prompt, Password: &secret, Category: category}}
}

// Manifest entry with the page its value is obtained from
func (p PlatformEnvVar) at(url string) PlatformEnvVar {
	p.Var.URL = &url
	return p
}

// Variables the manifests of the compiled in messaging platforms declare, platforms in name order
func BundledPlatformEnv() []PlatformEnvSet {
	sets := bundledPlatformTable()
	for i := range sets {
		sets[i].Name = sets[i].Dir + "-platform"
	}
	return sets
}

